csui.define('dctmw/controls/tree/impl/fancytree.dnd5.keyboard',[
 'nuc/lib/jquery',
 'nuc/lib/underscore',
 'dctmw/lib/fancytree/jquery.fancytree'
], function ($, _) {
  'use strict';

  var hitModes = ['before', 'over', 'after'],
    hitModeDropMarkerClasses = {
      before: 'fancytree-drop-before',
      over: 'fancytree-drop-over',
      after: 'fancytree-drop-after'
    };

  function getDndMode(data) {
    return data.tree.ext['dnd5-keyboard'].dndMode;
  }

  function setDndMode(data, enabled) {
    data.tree.ext['dnd5-keyboard'].dndMode = !!enabled;
  }

  function getHitMode(data) {
    return data.tree.ext['dnd5-keyboard'].hitMode;
  }

  function setHitMode(data, value) {
    data.tree.ext['dnd5-keyboard'].hitMode = value;
  }


  /************************************************ Drag image ************************************************/
  function setDragImagePosition($dragImage, data, hitMode) {
    var $targetElement = $(data.node.tr || data.node.span).find("span.fancytree-title"),
      imageOffsetX = data.options.dnd5.dropMarkerOffsetX || 0,
      imageOffsetY = hitMode === 'after' ? $targetElement.outerHeight()/2 : hitMode === 'before' ? -($targetElement.outerHeight()/2) : 0,
      rtl = data.options.rtl,
      offsetString = (n) => {return n === 0 ? "" : n > 0 ? "+" + n : "" + n},
      position = $.ui.fancytree.fixPositionOptions({
        my: (rtl ? 'right' : 'left') + offsetString(rtl ? -imageOffsetX : imageOffsetX) + ' top' + offsetString(imageOffsetY),
        at: (rtl ? 'right' : 'left') + ' center',
        of: $targetElement,
        collision: 'none fit'
      });

    $dragImage.position(position);
  }

  function addDragImage(data, dataTransfer) {
    var options = data.options['dnd5-keyboard'];
    if (!options.dragImage) {
      return;
    }

    var $targetElement = $(data.node.tr || data.node.span).find("span.fancytree-title"),
      $dragImage = _.isFunction(options.dragImage) ? options.dragImage(_.extend(data, {nodes: getDragNodes(data)})) //Get from options if configured
        : $(dataTransfer.getDragImage()).clone(); //Get from dnd5

    $dragImage.addClass(options.dragImageKBClass).css({height: $targetElement.outerHeight()}).prependTo(data.tree.$container);
    setDragImagePosition($dragImage, data);
  }

  function moveDragImageToNode(data, hitMode) {
    var options = data.options['dnd5-keyboard'];
    if (!options.dragImage) {
      return;
    }

    var $dragImage = data.tree.$container.find('.' + options.dragImageKBClass);
    setDragImagePosition($dragImage, data, hitMode);
  }

  function removeDragImage(data) {
    var options = data.options['dnd5-keyboard'];
    if (!options.dragImage) {
      return;
    }

    data.tree.$container.find('.' + options.dragImageKBClass).remove();
  }
  /************************************************ Drag image ************************************************/


  function createEvent(type, data, hitMode) {
    var target = data.node.tr || data.node.span,
      relPosY = hitMode === 'after' ? 0.76 : hitMode === 'before' ? 0.24 : 0.5, //These thresholds are set by dnd5 ('after' - >0.75, 'before' - <0.25)
      dataTransfer = {
        types: ['', 'application/x-fancytree-node'], setData: ()=>{}, getData: ()=>{},
        setDragImage: (dragImage) => {dataTransfer.dragImage = dragImage}, getDragImage: () => {return dataTransfer.dragImage} //To get drag image set by dnd5
      };

    return {
      type: type,
      dataTransfer: dataTransfer,
      pageY: relPosY * $(target).height() + $(target).offset().top, //To manipulate hitMode
      originalEvent: {}, stopPropagation: ()=>{}, preventDefault: ()=>{}
    }
  }

  function getDragNodes(data) {
    var dragNodeList = [];
    data.tree.visit(node => {
      node && node.dragStartKeyboard && dragNodeList.push(node);
      return true;
    });
    return dragNodeList;
  }

  function clearStylesAndDeactivateDndMode(data) {
    if (!getDndMode(data)) {
      return;
    }

    onFocusOutNode(data);
    removeDragImage(data);

    getDragNodes(data).forEach(dragNode => {
      $(dragNode.tr || dragNode.span).trigger(createEvent('dragend', {node: dragNode}));
      $(dragNode.tr || dragNode.span).removeClass(data.options['dnd5-keyboard'].dragNodeKBClass);
      dragNode.dragStartKeyboard = false;
    });

    setDndMode(data, false);
    setHitMode(data, null);
  }

  function checkDropSupport(data, hitMode) {
    //Triggering dragleave before dragover to clear off autoexpand.
    data && data.node && $(data.node.tr || data.node.span).trigger(createEvent('dragleave', data));
    // Dnd API madness: to PREVENT default handling to enable dropping, the return value is set to false in case of allowed
    return data && data.node && $.event.trigger(createEvent('dragenter', data, hitMode), undefined, data.node.tr || data.node.span) === false
             && $.event.trigger(createEvent('dragover', data, hitMode), undefined, data.node.tr || data.node.span) === false;
  }

  function moveHitMode(data, direction, checkCurrentHitMode) {
    var index = hitModes.indexOf(getHitMode(data)),
      node = data.node,
      moveHitModeFn = (hitMode) => {
        if (checkDropSupport(data, hitMode)
          //This condition is to verify whether the drop is supported for the 'hitMode' used.
          //dragEnter dnd5 event returns positive in case even if one of the mode is allowed so need to check this way for verifying hitMode.
          && $(data.options.dnd5.dropMarkerParent).find('#fancytree-drop-marker').hasClass(hitModeDropMarkerClasses[hitMode])
        ) {
          moveDragImageToNode(data, hitMode);
          $(node.tr || node.span).addClass(data.options['dnd5-keyboard'].dropNodeKBClass);
          node.dragOverKeyboard = true;
          setHitMode(data, hitMode);
          return false;
        }
        return true;
      }

    node.dragOverKeyboard = false;
    if (index !== -1) {
      direction === 'up' && hitModes.slice(0, checkCurrentHitMode ? index + 1 : index).reverse().every(moveHitModeFn);
      direction === 'down' && hitModes.slice(checkCurrentHitMode ? index : index + 1).every(moveHitModeFn);
    }
  }

  /************************************************ Tree events ************************************************/
  function onFocusOutTree(event, tree) {
    clearStylesAndDeactivateDndMode({tree: tree, node: $.ui.fancytree.getNode(event), options: tree.options});
  }
  /************************************************ Tree events ************************************************/


  /************************************************ Node events ************************************************/
  function onBeforeExpandCollapseNode(event, data) {
    //Continue only if in drag mode and node is collapsing
    if (!getDndMode(data) || !data.node?.isExpanded()) {
      return;
    }

    var node = data.node,
      hasDragNodes = false;

    //Traverse all children of the node to find if any of them are drag nodes
    node.visit(childNode => {
      hasDragNodes = !!childNode.dragStartKeyboard;
      return !hasDragNodes; //Continue traversing if not drag node
    });

    hasDragNodes && clearStylesAndDeactivateDndMode(data);
  }

  function onClickNode(event, data) {
    clearStylesAndDeactivateDndMode(_.extend(_.clone(data), {node: data.tree.focusNode}));
  }

  function onFocusNode(event, data) {
    if (!getDndMode(data)) {
      return;
    }

    //First time focus the hitmode would be undefined
    setHitMode(data, getHitMode(data) || 'over');
    moveHitMode(data, getHitMode(data) === 'after' ? 'up' : 'down', true);

    //If drop not allowed then show the drag image at 'over' position
    if (!data.node.dragOverKeyboard) {
      setHitMode(data, null);
      moveDragImageToNode(data, 'over');
    }
  }

  function onFocusOutNode(data) {
    if (!getDndMode(data)) {
      return;
    }

    if (data && data.node) {
      $(data.node.tr || data.node.span).trigger(createEvent('dragleave', data));
      $(data.node.tr || data.node.span).removeClass(data.options['dnd5-keyboard'].dropNodeKBClass);
      data.node.dragOverKeyboard = false;
    }
  }

  function onKeyDownNode(event, data) {
    var tree = data.tree,
      node = data.node,
      dndOptions = data.options.dnd5,
      options = data.options['dnd5-keyboard'];

    //Ctrl + (Enter/space) to activate drag mode if drag allowed
    if ((event.which === 13 || event.which === 32) && event.ctrlKey && !getDndMode(data)) {
      var dragStartEvent = createEvent('dragstart', data);
      if (node && $.event.trigger(dragStartEvent, undefined, node.tr || node.span)) {
        event.stopPropagation();
        event.preventDefault();

        var dragNodeList = dndOptions.multiSource ? tree.getSelectedNodes() : [node];
        dragNodeList = dragNodeList.includes(node) ? dragNodeList : [node];

        dragNodeList.forEach(dragNode => {
          if (dragNode) {
            $(dragNode.tr || dragNode.span).addClass(options.dragNodeKBClass);
            dragNode.dragStartKeyboard = true;
          }
        });

        setDndMode(data, true);
        addDragImage(data, dragStartEvent.dataTransfer);
        onFocusNode(event, data);
      }
      return;
    }

    //Only proceed if drag mode
    if (!getDndMode(data)) {
      return;
    }

    //Escape to deactivate drag mode
    if (event.which === 27) {
      clearStylesAndDeactivateDndMode(data);
    }

    //Up and down (iterate through hit-modes and pause on valid mode, else move on)
    if (event.which === 38 || event.which === 40) {
      moveHitMode(data, event.which === 38 ? 'up' : 'down');
      if (node.dragOverKeyboard) {
        event.stopPropagation();
        event.preventDefault();
      } else {
        //If moving on to next node set hit mode to match direction
        setHitMode(data, event.which === 38 ? 'after' : 'before');
      }
    }

    //Enter or Space to drop
    if (event.which === 13 || event.which === 32) {
      event.stopPropagation();
      event.preventDefault();

      if (checkDropSupport(data, getHitMode(data))) {
        removeDragImage(data); //Have to remove drag image before triggering the drop event since its added to tree and interferes with fancytree drop logic
        $(data.node.tr || data.node.span).trigger(createEvent('drop', data, getHitMode(data)));
        clearStylesAndDeactivateDndMode(data);
      }
    }
  }
  /************************************************ Node events ************************************************/


  $.ui.fancytree.registerExtension({
    name: 'dnd5-keyboard',
    version: '1.0.0',

    options: {
      dragNodeKBClass: 'd4-tree-drag-kb-node', //The nodes being dragged class
      dropNodeKBClass: 'd4-tree-drop-kb-node', //The node being dropped on class
      dragImageKBClass: 'd4-tree-drag-kb-image', //Drag image class
      dragImage: true //falsy to not show drag image. Function to return a jQuery DOM element which will be used as dragimage. Truthy to pick up dragImage set via dnd5.
    },

    /** Adding these here for UTs **/
    _getDndMode: getDndMode,
    _setDndMode: setDndMode,
    _getHitMode: getHitMode,
    _setHitMode: setHitMode,
    _setDragImagePosition: setDragImagePosition,
    _addDragImage: addDragImage,
    _moveDragImageToNode: moveDragImageToNode,
    _removeDragImage: removeDragImage,
    _createEvent: createEvent,
    _getDragNodes: getDragNodes,
    _clearStylesAndDeactivateDndMode: clearStylesAndDeactivateDndMode,
    _checkDropSupport: checkDropSupport,
    _onFocusOutTree: onFocusOutTree,
    _onBeforeExpandCollapseNode: onBeforeExpandCollapseNode,
    _onClickNode: onClickNode,
    _onFocusNode: onFocusNode,
    _onFocusOutNode: onFocusOutNode,
    _onKeyDownNode: onKeyDownNode,
    /*******************************/

    nodeRenderStatus: function (ctx={}) {
      var res = this._super(ctx),
        tree = ctx.tree,
        node = ctx.node;

      //On any kb navigation, nodeRenderStatus is called for both "from" and "to" nodes and all the drag styling classes are removed.
      //Re-triggering drag events on drag nodes only if in drag mode
      if (getDndMode({tree: tree})) {
        if (node && node.dragStartKeyboard) {
          $(node.tr || node.span).trigger(createEvent('dragstart', {node: node}));
        }

        if (node && node.dragOverKeyboard) {
          $(node.tr || node.span).trigger(createEvent('dragleave', {node: node})); //To clear auto-expand timer
          $(node.tr || node.span).trigger(createEvent('dragenter', {node: node}, getHitMode({tree: tree})));
          $(node.tr || node.span).trigger(createEvent('dragover', {node: node}, getHitMode({tree: tree})));
        }

        //Handle focus out here since this is called after navigation
        node !== tree.focusNode && onFocusOutNode({tree: tree, node: node, options: ctx.options});
      }

      return res;
    },

    treeInit: function (ctx) {
      var FT = $.ui.fancytree,
        tree = ctx.tree,
        ext = tree.ext['dnd5-keyboard'];

      if (!tree.ext['dnd5']) {
        $.error("Extension 'dnd5' is required.");
      }

      FT.overrideMethod(ctx.options, 'keydown', (event, data) => {
        !getDndMode(data) && ext._super.call(this, event, data);
        if (event.isPropagationStopped()) {
          return;
        }
        onKeyDownNode(event, data);
      }, ext);

      FT.overrideMethod(ctx.options, 'focus', (event, data) => {
        ext._super.call(this, event, data);
        if (event.isPropagationStopped()) {
          return;
        }
        onFocusNode(event, data);
      }, ext);

      FT.overrideMethod(ctx.options, 'click', (event, data) => {
        ext._super.call(this, event, data);
        if (event.isPropagationStopped()) {
          return;
        }
        onClickNode(event, data);
      }, ext);

      tree.$container.on('focusout', event => {
        onFocusOutTree(event, tree);
      });

      FT.overrideMethod(ctx.options, 'beforeExpand', (event, data) => {
        ext._super.call(this, event, data);
        if (event.isPropagationStopped()) {
          return;
        }
        onBeforeExpandCollapseNode(event, data);
      }, ext);

      this._superApply(arguments);
    }
  });

  return $.ui.fancytree;
});