csui.define('dctmw/controls/form/fields/alpaca/alpdctmwurlfield',['nuc/lib/underscore', 'nuc/lib/jquery', 'nuc/lib/backbone',
  'nuc/lib/marionette', 'csui/lib/alpaca/js/alpaca.lite', 'csui/controls/form/fields/alpaca/alpcsuiurlfield',
  'dctmw/controls/form/fields/dctmwurlfield.view', 'nuc/utils/base',
], function (_, $, Backbone, Marionette, Alpaca, CsuiUrlField, URLFieldView) {

  Alpaca.Fields.DctmwUrlField = Alpaca.Fields.CsuiUrlField.extend({

    dctmwUrlregexps: /(^(http|https|ftp):\/\/)?[a-z0-9]+([\-\.]{1}[a-z0-9]+)*(\:[0-9]{1,5})?(\/.*)?$/i,

    constructor: function DctmwUrlField(container, data, options, schema, view, connector, onError) {
      this.base(container, data, options, schema, view, connector, onError);
    },


    setup: function () {
      this.base();
      /*
      DCTM specific URL Pattern
      */
      this.schema.pattern = this.dctmwUrlregexps;
    },

    getFieldViewClass: function () {
      return URLFieldView;
    },

    showField: function () {

      var id = this.id,
        fieldViewClass = this.getFieldViewClass();

      // our field
      this.fieldView = new fieldViewClass({
        model: new Backbone.Model({
          data: this.data,
          options: this.options,
          schema: this.schema,
          id: id
        }),
        id: _.uniqueId(id), // wrapper <div>
        alpacaField: this,
        value: this.data,
        readonly: true,
        dataId: this.name,
        path: this.path,
        alpaca: {
          data: this.data,
          options: this.options,
          schema: this.schema
        }
      });

      // replace alpaca control with empty div having same classes as control
      var $field = $('<div>').addClass('alpaca-control');
      this.getControlEl().replaceWith($field);

      // show our field in div
      this.region = new Marionette.Region({ el: $field });
      this.region.show(this.fieldView);

      return;
    },
    handleValidate: function () {
      return this.base();
    }
  });

  Alpaca.registerFieldClass('dctmwurl', Alpaca.Fields.DctmwUrlField, 'bootstrap-csui');
  Alpaca.registerFieldClass('dctmwurl', Alpaca.Fields.DctmwUrlField, 'bootstrap-edit-horizontal');

  return $.alpaca.Fields.DctmwUrlField;
});