

export default {
    /**
     * Initializes the expiration dialog based on the provided configuration.
     *
     * @param {Object} config - The configuration object.
     * @param {number} [config.sessionTimeout] - The session timeout in seconds.
     * @param {number} [config.sessionTimeoutTimer] - The session timeout timer in seconds.
     * @param {boolean} [config.allowTokenRefresh] - Indicates if token refresh is allowed.
     * @param {number} [config.kindnessPeriod=3] - The kindness period in seconds.
     */
    reConfigureUserSessionModule: function (config) {
        const sessionTimeout = config.sessionTimeout;

        if (sessionTimeout) {
            const sessionTimeoutTimer = config.sessionTimeoutTimer;

            //     0 = never expires (no additional params available)
            //     1 = expire after last request
            //     2 = expire after last login
            const allowTokenRefresh = config.allowTokenRefresh ? 1 : 2,
                kindnessPeriod = (config.kindnessPeriod || 3) * 1000;

            csui.require.undef('dctmw/overrides/csui/utils/user.session');
            csui.require.undef('csui/utils/user.session/user.session');

            csui.require.config({
                config: {
                    'csui/utils/user.session/user.session': {
                        enableExpirationHandling: true,
                        sessionInactivity: (sessionTimeout - sessionTimeoutTimer) * 1000,
                        kindnessPeriod: kindnessPeriod,
                        sessionReactionTime: sessionTimeoutTimer * 1000,
                        cookieExpirationMode: allowTokenRefresh
                    }
                }
            });
            /**
            * done as part of 23.4 refactoring as the modules had to be explicitly loaded again to have the overriding to work
            */
            csui.require(['dctmw/overrides/csui/utils/user.session'], function (/*D2UserSession*/) {

            });
        }

    }
}