csui.define('dctmw/overrides/csui/controls/form/fields/alpaca/alpcsuidatetimefield',['nuc/lib/underscore', 'nuc/lib/jquery',
  'nuc/lib/backbone', 'nuc/lib/marionette',
  'csui/controls/form/fields/alpaca/alpcsuidatetimefield',
  'dctmw/utils/form.utils',
  'dctmw/utils/utils',
  'csui/controls/form/fields/datetimefield.view',
  'nuc/utils/types/date',
  'dctmw/utils/types/inputdate',
  'dctmw/utils/constants'
], function (_, $, Backbone, Marionette, CsuiDateTimeField, FormUtils, utils, DateTimeFieldView, date, inputDate, constants) {

  var prototype = CsuiDateTimeField.prototype;
  var originalSetValue = prototype.setValue;
  var originalGetValue = prototype.getValue;
  var oldIsRequired = prototype.isRequired;
  var oldIsValidationParticipant = prototype.isValidationParticipant;

  prototype._validateOptional = function () {
    return FormUtils._validateOptional(this);
  };

  prototype.setValue = function (value) {
    value = value === null ? '' : value;
    return originalSetValue.call(this, value);
  };

  prototype.getValue = function () {
    var value = originalGetValue.apply(this, arguments);
    value = value === null ? '' : value;
    return value;
  };

  prototype._validateDateFormat = function () {
      return this._validateDateCustomFormat.call(this);

  };


  prototype.isValidationParticipant = function () {
    var result = oldIsValidationParticipant.apply(this, arguments);
    return result && !this.schema.disabled;
  };

  prototype.isRequired = function () {
    var result = oldIsRequired.apply(this, arguments);
    return result && !this.schema.disabled;
  };

  // DTWO-115882 - Honor Date Formats
  // showField method overridden to set format to input datetime format if this field is in edit mode
  prototype.showField = function () {
    // our field
    var id = this.id;
    // add an id to the <label> element like alpaca23Label
    var id4Label,
        id4Description = this.options ? this.options.descriptionId : '',
        labelElement = $(this.field[0]).find('label');

    if (labelElement && labelElement.length == 1) {
      id4Label = labelElement.attr('for') + "Label";
      labelElement.attr('id', id4Label);
    }

    this.fieldView = new DateTimeFieldView({
      model: new Backbone.Model({
        data: this.data,
        options: this.options,
        schema: this.schema,
        inputType: 'text',
        id: id // <input type=

      }),
      id: _.uniqueId(id), // wrapper <div>
      alpacaField: this,
      labelId: id4Label,
      descriptionId: id4Description,
      value: this.data,
      readonly: true,
      dataId: this.name,
      path: this.path,
      alpaca: {
        data: this.data,
        options: this.options,
        schema: this.schema
      }
    });

    if (this.fieldView.mode === 'writeonly') {
      this.fieldView.format = inputDate.exactDateTimeInputFormat;
    }

    // replace alpaca control with empty div having same classes as control
    var $field = $('<div>').addClass('alpaca-control');
    this.getControlEl().replaceWith($field);

    // show our field in div
    this.region = new Marionette.Region({el: $field});
    this.region.show(this.fieldView);
  };

  // DTWO-115882 - Honor Date Formats
  // validateDateCustomFormat -> Similar to prototypes _validateDateFormat function -> here we pass input datetime format for validating
  prototype._validateDateCustomFormat = function () {
    var parseFormat = inputDate.exactDateTimeInputFormat;
    if (utils.isMobile()) {
      parseFormat = constants.ISODateFormats.DATE_TIME_INPUT;
    }
    var value = this.containerItemEl.find('input').val();
    if (!value && this.isRequired()) return false;
    if (!this.validateDateRange()) return false;
    return !value || date.validateDateTime(value, parseFormat);
  };
});