csui.define('dctmw/controls/tree/tree.view',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/marionette',
  'i18n',
  'nuc/models/node/node.model',
  'nuc/utils/base',
  'dctmw/controls/tree/tree.sprites',
  'dctmw/lib/fancytree/jquery.fancytree',
  'dctmw/controls/tree/impl/fancytree.overrides',
  'dctmw/controls/tree/impl/fancytree.dnd5.keyboard',
  'dctmw/lib/fancytree/jquery.fancytree.dnd5',
  'css!dctmw/controls/tree/impl/tree'
], function ($, _, Marionette, i18n, NodeModel, base, TreeSprites) {
  'use strict';
  
  const treeNodePropertiesToUseInIconMatch = ['statusNodeType', '_isLoading', '_error', 'data', 'checkbox', 'expanded', 'extraClasses', 'folder', 'icon', 'iconTooltip', 'key', 'lazy', 'partsel', 'refKey', 'selected', 'title', 'tooltip', 'type', 'unselectable', 'unselectableIgnore', 'unselectableStatus', 'children'];

  return Marionette.ItemView.extend({

    template: false,
    className: 'd4-tree',

    constructor: function TreeView(options={}) {
      const optionsToPick = ['activate', 'beforeActivate', 'click', 'clickPaging', 'collapse', 'dblclick', 'expand',
        'focus', 'init', 'keydown', 'lazyLoad', 'source', 'strings', 'renderNode'];
      const dctmwDNDOptions = ['onDragStart', 'onDragEnd', 'onDragDrag', 'onDragEnter', 'onDragOver', 'onDragLeave',
        'onDragExpand', 'onDragDrop', 'dropNodeParentClass', 'dropNodeClass', 'dragNodeClass', 'dragImageClass',
        'dragImageNodeCountClass', 'dragImageBackLayerClass', 'expandBeforeDrop', 'dropNodesSortComparator'];

      if(_.isArray(options.extensions)) {
        options.extensions.forEach(e => optionsToPick.push(e));
      }

      Marionette.ItemView.prototype.constructor.call(this, _.omit(options, optionsToPick));

      //Drag and drop support will only be enabled if dnd5 passed as part of extensions (dnd5-keyboard for keyboard support)
      options.dnd5 = _.extend(this._defaultDndOptions(options.dnd5), _.omit(options.dnd5, dctmwDNDOptions));
      options['dnd5-keyboard'] = _.extend({}, options['dnd5-keyboard']);

      this.treeOptions = _.extend(_.pick(options, optionsToPick), {
        escapeTitles: true,
        extensions: ['d4-overrides',...(options.extensions||[])],
        'd4-overrides': {
          rootIndent: 4,
          levelIndent: 24,
          levelIndentOnErrorNode: options.levelIndentOnErrorNode !== false
        },
        rtl: i18n && i18n.settings && i18n.settings.rtl,
        autoActivate: false,
        icon: function (event, data) {
          let treeNode = data.node,
            node = treeNode.data.origNode;
          if (!node) {
            node = new NodeModel({
              id: treeNode.key,
              _is_home_cabinet: treeNode.data._is_home_cabinet,
              statusNodeType: treeNode.statusNodeType
            });
          }
          return TreeSprites.findClassByNode(node) || TreeSprites.findClassByTreeNode(_.pick(treeNode, treeNodePropertiesToUseInIconMatch)) || false;
        }
      });
    },

    onBeforeRender: function () {
      this.tree = $.ui.fancytree.getTree(this.$el.fancytree(this.treeOptions));
    },

    onBeforeDestroy: function () {
      this.tree?.widget?.destroy();
      this.$el.find('#fancytree-drop-marker').remove();
    },

    _defaultDndOptions: function (dndOptions={}) {
      var me = this,
        DROP_NODE_PARENT_CLASS = dndOptions.dropNodeParentClass || 'd4-tree-drop-parent',
        DROP_NODE_CLASS = dndOptions.dropNodeClass || 'd4-tree-drop-node',
        DRAG_NODE_CLASS = dndOptions.dragNodeClass || 'd4-tree-drag-node',
        DRAG_IMAGE_CLASS = dndOptions.dragImageClass || 'd4-tree-drag-image',
        DRAG_IMAGE_NODE_COUNT_CLASS = dndOptions.dragImageNodeCountClass || 'd4-tree-drag-image-node-count',
        DRAG_IMAGE_BACK_LAYER_CLASS = dndOptions.dragImageBackLayerClass || 'd4-tree-drag-image-back-layer';

      return {
        autoExpandMS: 800, // Expand nodes after n milliseconds of hovering.
        dropMarkerInsertOffsetX: -16, // Additional offset for drop-marker with hitMode = "before"/"after"
        dropMarkerOffsetX: -28, // Absolute position offset for .fancytree-drop-marker relatively to ..fancytree-title (icon/img near a node accepting drop)
        dropMarkerParent: this.$el, // Root Container used for drop marker (could be a shadow root)
        dropEffectDefault: 'move', // Default dropEffect ('copy', 'link', or 'move').
        multiSource: false, // Drag multiple (i.e. selected) nodes.
        preventForeignNodes: true, // Prevent dropping nodes from another fancytree
        preventNonNodes: true, // Prevent dropping items other than Fancytree nodes
        preventRecursiveMoves: true, // Prevent dropping nodes on own descendants when in move-mode
        preventVoidMoves: true, // Prevent moving nodes 'before self', etc.
        scroll: true, // Enable auto-scrolling while dragging
        scrollSensitivity: 15, // Active top/bottom margin in pixel
        scrollSpeed: 15, // Pixel per event
        setTextTypeJson: false, // Allow dragging of nodes to different IE windows


        /************************************     Events (drag support)     *******************************************/
        dragStart: function (sourceNode, data) {
          //Return false to prevent the node from being dragged
          var sourceNodeList = dndOptions.multiSource ? data.tree.getSelectedNodes() : [sourceNode];
          sourceNodeList = sourceNodeList.includes(sourceNode) ? sourceNodeList : [sourceNode];

          //Status nodes should not be draggable
          if (sourceNodeList.find(node => node.isStatusNode())) {
            return false;
          }

          var allowDrag = _.isFunction(dndOptions.onDragStart) ? dndOptions.onDragStart(sourceNode, data) : true;

          //Fancytree dnd adds a class only to span, adding our own logic for table extension
          //When using table extension add class to tr
          allowDrag && sourceNodeList.forEach(node => $(node.tr || node.span).addClass(DRAG_NODE_CLASS));

          return allowDrag;
        },

        dragEnd: function (sourceNode, data) {
          var sourceNodeList = dndOptions.multiSource ? data.tree.getSelectedNodes() : [sourceNode];
          sourceNodeList = sourceNodeList.includes(sourceNode) ? sourceNodeList : [sourceNode];

          //When using table extension add class to tr
          sourceNodeList.forEach(node => $(node.tr || node.span).removeClass(DRAG_NODE_CLASS));
          me.$el.find('.' + DROP_NODE_PARENT_CLASS).removeClass(DROP_NODE_PARENT_CLASS);
          me.$el.find('.' + DROP_NODE_CLASS).removeClass(DROP_NODE_CLASS);

          _.isFunction(dndOptions.onDragEnd) && dndOptions.onDragEnd(sourceNode, data);
        },

        dragDrag: function (sourceNode, data) {
          _.isFunction(dndOptions.onDragDrag) && dndOptions.onDragDrag(sourceNode, data);
        },
        /**************************************************************************************************************/


        /************************************     Events (drop support)     *******************************************/
        dragEnter: function (targetNode, data) {
          //Return false to prevent the node from being dropped at the target node
          //Can also return object specifying if before/over/after drops are allowed or not individually {before: true, over: false, after: true}
          //The control reaches here if it passes the checks for preventForeignNodes, preventNonNodes if enabled
          //and preventRecursiveMoves(not supported for multiSource by fancytree dnd) if enabled
          var allowDrop = true,
            selectedNodeList = [];

          if (data.otherNode) {
            selectedNodeList = dndOptions.multiSource ? data.tree.getSelectedNodes() : [data.otherNode];
            selectedNodeList = selectedNodeList.includes(data.otherNode) ? selectedNodeList : [data.otherNode];
          }

          if (targetNode.isStatusNode() //Status nodes should not be droppable
            || (dndOptions.preventRecursiveMoves !== false && !!selectedNodeList.find(node => targetNode.isDescendantOf(node))) //Prevent recursion if enabled
          ) {
             allowDrop = false;
          }

          allowDrop = allowDrop && (_.isFunction(dndOptions.onDragEnter) ? dndOptions.onDragEnter(targetNode, data) : true);
          !allowDrop && me.$el.find('#fancytree-drop-marker').hide(); //Hiding dropmarker in case drag enter returns false
          return allowDrop;
        },

        dragOver: function (targetNode, data) {
          //The control reaches here if it passes the checks for preventVoidMoves if enabled (not supported for multiSource by fancytree dnd)
          //Can set data.hitMode = null to not allow drop
          if (dndOptions.preventVoidMoves !== false && data.otherNode) {
            var selectedNodeList = dndOptions.multiSource ? data.tree.getSelectedNodes() : [data.otherNode];
            selectedNodeList = selectedNodeList.includes(data.otherNode) ? selectedNodeList : [data.otherNode];

            //Prevent drop where even one of the selected node will end up in the same position
            selectedNodeList.forEach(node => {
              if (node == targetNode
                || (data.hitMode === "before" && node.getNextSibling() === targetNode)
                || (data.hitMode === "after" && node.getPrevSibling() === targetNode)
                || (data.hitMode === "over" && node.parent === targetNode && node.isLastSibling())
              ) {
                data.hitMode = null;
              }
            });

            if (data.hitMode === null) {
              return;
            }
          }

          me.$el.find('.' + DROP_NODE_PARENT_CLASS).removeClass(DROP_NODE_PARENT_CLASS);
          me.$el.find('.' + DROP_NODE_CLASS).removeClass(DROP_NODE_CLASS);

          //When using table extension add class to tr
          data.hitMode === 'over' ? $(targetNode.tr || targetNode.span).addClass(DROP_NODE_PARENT_CLASS)
            : $(targetNode.parent.tr || targetNode.parent.span).addClass(DROP_NODE_PARENT_CLASS);
          $(targetNode.tr || targetNode.span).addClass(DROP_NODE_CLASS);

          _.isFunction(dndOptions.onDragOver) && dndOptions.onDragOver(targetNode, data);
        },

        dragLeave: function (targetNode, data) {
          me.$el.find('.' + DROP_NODE_PARENT_CLASS).removeClass(DROP_NODE_PARENT_CLASS);
          me.$el.find('.' + DROP_NODE_CLASS).removeClass(DROP_NODE_CLASS);
          _.isFunction(dndOptions.onDragLeave) && dndOptions.onDragLeave(targetNode, data);
        },

        dragExpand: function (targetNode, data) {
          //Return false to prevent autoExpand
          return _.isFunction(dndOptions.onDragExpand) ? dndOptions.onDragExpand(targetNode, data) : true;
        },

        dragDrop: function (targetNode, data) {
          //Action to perform after drop
          var performMove = function () {
            //on drag drop to return a promise after which the node will be moved
            var dropCallbackPromise = _.isFunction(dndOptions.onDragDrop) ? dndOptions.onDragDrop(targetNode, data) : $.Deferred().resolve().promise();

            var selectedNodeList = dndOptions.multiSource ? data.tree.getSelectedNodes() : [data.otherNode];
            selectedNodeList =  selectedNodeList.includes(data.otherNode) ? selectedNodeList : [data.otherNode];

            selectedNodeList = _.clone(selectedNodeList);
            //Drop nodes sort comparator (Default behavior to not sort)
            selectedNodeList.sort(_.isFunction(dndOptions.dropNodesSortComparator) ? dndOptions.dropNodesSortComparator : () => {});
            dropCallbackPromise.done(() => selectedNodeList.forEach(node => node.moveTo(targetNode, data.hitMode)));
          }

          data.hitMode === 'over' && dndOptions.expandBeforeDrop !== false ? targetNode.setExpanded().done(performMove) : performMove();
        },
        /**************************************************************************************************************/

        /*
          - Don't set dragImage to use dctmw drag image.
          - Set dragImage as false to get the fancytree drag image.
          - Set custom drag image using "setDragImage" in dragImage callback. If "setDragImage" not used and callback left empty, the image will be set by browser.
        */
        dragImage: function (sourceNode, data) {
          var selectedNodeList = dndOptions.multiSource ? data.tree.getSelectedNodes() : [sourceNode];
          selectedNodeList =  selectedNodeList.includes(sourceNode) ? selectedNodeList : [sourceNode];

          var $dragImage = $(_.str.sformat('<div class="{0}"></div>', DRAG_IMAGE_CLASS)).html((sourceNode.tr || sourceNode.span).outerHTML),
            $node = $dragImage.find('> tr, > span'),
            multiSelect = selectedNodeList.length > 1;

          multiSelect && $node.append($(_.str.sformat(
            '<div class="{0}">{1}</div><div class="{2}"></div>', DRAG_IMAGE_NODE_COUNT_CLASS, selectedNodeList.length, DRAG_IMAGE_BACK_LAYER_CLASS
            )));

          //Drag image has to be part of DOM for setDragImage to pick it up
          $dragImage.appendTo(me.$el);
          setTimeout(() => $dragImage.remove());

          //Firefox fades the drag image if the width is greater than 300px
          base.isFirefox() && $node.css({width: '295px', 'max-width': '295px'});

          var offsetX = i18n && i18n.settings?.rtl ?
                            base.isFirefox() ? $node.outerWidth() - 5 : $dragImage.width() - 5
                            : 5,
              offsetY = multiSelect ? 25 : 14;
          data.dataTransfer.setDragImage && data.dataTransfer.setDragImage($dragImage[0], offsetX, offsetY);
        }
      }
    }
  });
});