csui.define('dctmw/server.adaptors/models/nuc/authenticated.user.mixin',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'dctmw/utils/rest.resources'
], function ($, _, RestResources) {
  'use strict';

  return {

    mixin: function (prototype) {
      
      return _.extend(prototype, {
        makeServerAdaptor: function (/*options*/) {
          return this;
        },

        sync: function (method, model, options) {
          if (method === 'read') {
            var deferred = $.Deferred(),
              user = RestResources.getCurrentUser();

            options.parse = false;
            this.trigger('request', this, {}, options);
            setTimeout(function () {
              options.success.call(options.context, user.attributes, 'success', {});
              deferred.resolve();
            });

            return deferred.promise();
          }
          
          throw new Error('Only read is supported');
        }
      });
    }

  };

});
