import Url from 'nuc/utils/url';

export default {
    mixin: (prototype) => {
        return Object.assign(prototype, {
            makeServerAdaptor: function(/*options*/) {
                return this;
            },

            url: function() {
                return Url.combine(this.connector.connection.url, 'product-info');
            }
        });
    }
};