csui.define('dctmw/models/mixins/expressions/expression.validator.mixin',[
  'module', 'nuc/lib/underscore', 'nuc/lib/backbone', 'nuc/utils/log', 'dctmw/models/mixins/expressions/expression'
], function (module, _, Backbone, log, ExpressionModel) {
  'use strict';

  log = log(module.id);

  var ExpressionValidatorMixin = {

    mixin: function (prototype) {

      return _.extend(prototype, {

        expressionValidator: function (/*options*/) {
          return this;
        },

        /**
         * post evaluation option for clients to evaluate the value for the control
         * @param value
         * @returns {*}
         */
        getValueForCreateExpressionValidator: function(targetAlpControl){
          var formView = this;
          return function (controlName) {
            var value;
            var control;
            if (targetAlpControl.propertyId === controlName) {
              value = targetAlpControl.getValue();
              control = targetAlpControl;
            } else {
              var controlPathObj = formView._keyPathMap[controlName];
              if (controlPathObj) {
                var sourceForm = formView.getParentFormForControl(controlName);
                var sourceAlpControl = sourceForm.getAlpacaControlByPath(controlPathObj.fieldPath);
                if (_.isArray(sourceAlpControl)) {
                  control = sourceAlpControl;
                  value = _.pluck(sourceAlpControl, 'data');
                } else {
                  value = sourceAlpControl.getValue();
                  control = sourceAlpControl;
                }
              }
            }
            return new ExpressionModel(value, control, true);
          };
        },

        createExpressionValidator: function (condition, message) {
          var formView = this;
          var evtHandler = function (targetAlpControl) {
            var getValue = formView.getValueForCreateExpressionValidator(targetAlpControl);
            return formView.evaluate(condition, getValue);
          };
          //Create Validator
          var validator = function (callback) {
            var value = evtHandler(this);
            if (!value) {
              callback({
                "status": false,
                "message": message
              });
            } else {
              callback({
                "status": true
              });
            }
          };
          return validator;
        },

        /**
         * this method is written as a hook for the clients to set or process the values
         * @returns {*}
         */
        getPreExpressionValue: function(control){
          return control.getValue();
        },

        createRegExValidator: function (condition, message) {
          var me = this;
          var validator = function (callback) {
            var value = me.getPreExpressionValue(this);
            var reg;
            //Emulating GWT
            // https://gwt.googlesource.com/gwt/+/master/user/super/com/google/gwt/emul/java/lang/String.java
            /**
             * Regular expressions vary from the standard implementation. The
             * <code>regex</code> parameter is interpreted by JavaScript as a JavaScript
             * regular expression. For consistency, use only the subset of regular
             * expression syntax common to both Java and JavaScript.
             public boolean matches(String regex) {
              // We surround the regex with '^' and '$' because it must match the entire string.
              return new NativeRegExp("^(" + regex + ")$").test(this);
            }*/
            try {
              reg = new RegExp("^(" + condition + ")$");
            } catch (e) {
              console.error("Error creating regex for " + condition, e);
            }
            if (reg) {
              value = typeof value === 'number' ? value.toString() : value;// _.isEmpty does not recognize numbers
              if (!_.isUndefined(value) && !_.isNull(value) && !_.isEmpty(value) && !reg.test(value)) {
                callback({
                  "status": false,
                  "message": message
                });
              } else {
                callback({
                  "status": true
                });
              }
            }
          };
          return validator;
        }
      });
    }
  };
  return ExpressionValidatorMixin;
});
