csui.define('dctmw/dialogs/modal.alert.message/modal.alert.message.dialog.view',[
  'nuc/lib/marionette',
  'csui/controls/tile/behaviors/perfect.scrolling.behavior',
  'hbs!dctmw/dialogs/modal.alert.message/impl/modal.alert.message.dialog',
  'css!dctmw/dialogs/modal.alert.message/impl/modal.alert.message.dialog'
], function (Marionette, PerfectScrollingBehavior, template) {
  'use strict';

  return Marionette.ItemView.extend({
    template: template,
    className: 'custom-message-body',
    templateHelpers: function () {
      return {
        message: this.options.message
      }
    },
    behaviors: {
      PerfectScrolling: {
        behaviorClass: PerfectScrollingBehavior,
        contentParent: '#message-body-container',
        suppressScrollX: true
      }
    },
    constructor: function (options) {
      this.options = options || {};
      Marionette.ItemView.prototype.constructor.call(this, options);
    }
  });

});